import React, { Fragment, useState } from "react";
import {
  Col,
  Form,
  FormGroup,
  Label,
  Input,
  FormText,
  CustomInput
} from "reactstrap";
import { Button } from "@material-ui/core";
import axios from "axios";
export default function FileUpload() {
  const [file, setFile] = useState("");
  const onChange = e => {
    //e.preventDefault();
    setFile(e.target.files[1]);
  };
  const onSubmit = async e => {
    e.preventDefault();
    const formData = new FormData();
    formData.append("file", file);
    try {
      const res = await axios.post("/upload", formData, {
        hearders: {
          "Content-Type": "multipart/for-data"
        }
      });
    } catch (err) {}
  };
  return (
    <Fragment>
      <Form onSubmit={onSubmit}>
        <FormGroup row>
          <Button
            style={{ marginLeft: "1%" }}
            variant="contained"
            color="primary"
            type="submit"
            value="upload"
          >
            Load File
          </Button>

          <Col>
            <CustomInput
              type="file"
              id="exampleCustomFileBrowser"
              name="customFile"
              label="Upload Goal Geometry File - ASCII STL Files Only"
              onChange={onChange}
            />
          </Col>
        </FormGroup>
      </Form>
    </Fragment>
  );
}
